cd /workspace && cat > src/image_validate.cpp << 'EOF'
#include "image_validate.h"
#include "fib.h"

#include <algorithm>
#include <deque>
#include <string>
#include <utility>
#include <vector>

std::string scamp_validate_error;

#define FAILAT() (scamp_validate_error = std::string(__func__) + ":" + std::to_string(__LINE__), false)

namespace {

struct ChildRef {
    uint8_t key;
    int stage;
    uint32_t cell;
    int32_t node;
};

struct ValNode {
    int32_t stage = 0;
    uint32_t cell = 0;
    uint8_t slot = 0, rec = 0, type = NODE_NONE, origin = 0, depth = 0;
    uint32_t bmp = SCAMP_BMP_NULL, bitmap_id = 0, ni_base = 0;
    uint64_t pattern = 0;
    u128_t region = 0;
    int32_t parent = -1;
    uint32_t owned = 0;
    uint32_t ch_start = 0;
    uint8_t ch_count = 0;
    uint8_t ninl = 0;
    ScampPrefix inl[2];
};

struct Work {
    int stage = 0;
    uint32_t cell = 0;
    bool bulk = false;
    int origin = 0;
    int depth = 0;
    u128_t region = 0;
    int32_t parent = -1;
    int32_t ref = -1;
};

struct Validator {
    const ImageData* d = nullptr;
    ParsedImage* out = nullptr;
    std::vector<int32_t> cover[RAM_NUM];
    std::deque<ValNode> nodes;
    std::vector<ChildRef> children;
    std::vector<ScampPrefix> fib;
    std::vector<Work> q;

    bool run();
    bool shape();
    bool visit(const Work& w);
    bool finish();
    int32_t resolve(const ImageLoc& loc) const;
};

int32_t Validator::resolve(const ImageLoc& loc) const {
    if (loc.stage < 0 || loc.stage >= RAM_NUM) return -1;
    if (loc.cell >= d->cells[loc.stage]) return -1;
    int32_t id = cover[loc.stage][loc.cell];
    if (id < 0) return -1;
    if (nodes[id].cell != loc.cell) return -1;   /* must be the slot start */
    return id;
}

bool Validator::shape() {
    if (d->cells.size() != RAM_NUM || d->banks.size() != RAM_NUM) return FAILAT();
    if (d->front16.size() > SCAMP_FRONT_LIMIT) return FAILAT();
    if (d->front64.size() > SCAMP_FRONT_LIMIT) return FAILAT();
    if (d->bitmaps.size() > SCAMP_BITMAP_LIMIT) return FAILAT();
    if (d->nexthops.size() > SCAMP_NI_LIMIT) return FAILAT();
    uint64_t rows = 0;
    for (int s = 0; s < RAM_NUM; ++s) {
        if (d->cells[s] > SCAMP_CELL_LIMIT) return FAILAT();
        uint32_t want = (d->cells[s] + 1) / 2;
        if (d->banks[s].size() != want) return FAILAT();
        rows += want;
    }
    if (rows > SCAMP_ROW_LIMIT) return FAILAT();
    for (size_t i = 0; i < d->nexthops.size(); ++i)
        if (d->nexthops[i] > SCAMP_HOP_MAX) return FAILAT();
    if (d->root.stage != -1) {
        if (d->root.stage < 0 || d->root.stage > SCAMP_STAGE_MAX) return FAILAT();
        if (d->root.cell >= d->cells[d->root.stage]) return FAILAT();
    }
    for (int which = 0; which < 2; ++which) {
        const std::vector<ImageFront>& v = which ? d->front64 : d->front16;
        uint64_t limit = which ? ~0ULL : 0xFFFFULL;
        uint64_t prev = 0;
        for (size_t i = 0; i < v.size(); ++i) {
            if (v[i].key > limit) return FAILAT();
            if (i && !(prev < v[i].key)) return FAILAT();       /* sorted, unique */
            prev = v[i].key;
            if (v[i].loc.stage < 0 || v[i].loc.stage > SCAMP_STAGE_MAX) return FAILAT();
            if (v[i].loc.cell >= d->cells[v[i].loc.stage]) return FAILAT();
        }
    }
    return true;
}

bool Validator::visit(const Work& w) {
    int s = w.stage;
    if (s < 0 || s >= RAM_NUM) return FAILAT();
    uint32_t C = d->cells[s];
    if (w.cell >= C) return FAILAT();
    int max = scamp_origin_max(w.origin);
    if (w.depth < 0 || w.depth > max) return FAILAT();
    if ((w.depth - w.origin) % 6 != 0) return FAILAT();

    const Row256& row = d->banks[s][w.cell / 2];
    int base = (w.cell & 1u) ? 128 : 0;
    int type = static_cast<int>(pk_read(row, base + PK_TYPE_OFF, PK_TYPE_BITS));
    if (type < TYPE1 || type > TYPE5) return FAILAT();
    int rec = scamp_type_cells(type);
    if (rec == 2 && (w.cell & 1u)) return FAILAT();             /* even alignment */
    int slot = w.bulk ? 2 : rec;
    if (w.cell + static_cast<uint32_t>(slot) > C) return FAILAT();

    int32_t idx = static_cast<int32_t>(nodes.size());
    for (int k = 0; k < slot; ++k) {
        if (cover[s][w.cell + k] != -1) return FAILAT();        /* overlap / two parents */
        cover[s][w.cell + k] = idx;
    }
    if (slot == 2 && rec == 1) {                                /* bulk zero padding */
        if (!pk_zero(row, 128, 128)) return FAILAT();
    }

    nodes.emplace_back();
    ValNode& n = nodes[idx];
    n.stage = s;
    n.cell = w.cell;
    n.slot = static_cast<uint8_t>(slot);
    n.rec = static_cast<uint8_t>(rec);
    n.type = static_cast<uint8_t>(type);
    n.origin = static_cast<uint8_t>(w.origin);
    n.depth = static_cast<uint8_t>(w.depth);
    n.region = w.region;
    n.parent = w.parent;
    if (w.ref >= 0) children[w.ref].node = idx;

    n.bmp = static_cast<uint32_t>(pk_read(row, base + PK_BMP_OFF, PK_BMP_BITS));

    /* ---- NI header ---- */
    if (type <= TYPE3) {
        uint32_t bid = static_cast<uint32_t>(pk_read(row, base + PK_BID_OFF, PK_BID_BITS));
        uint32_t nib = static_cast<uint32_t>(pk_read(row, base + PK_NIB_OFF, PK_NIB_BITS));
        if (bid >= d->bitmaps.size()) return FAILAT();
        n.bitmap_id = bid;
        n.ni_base = nib;
        n.pattern = d->bitmaps[bid];
        if (n.pattern & 1ULL) return FAILAT();                  /* bit0 unused */
        uint32_t pc = scamp_popcount64(n.pattern);
        if (static_cast<uint64_t>(nib) + pc > d->nexthops.size()) return FAILAT();
        if (pc == 0 && nib != 0) return FAILAT();               /* empty arrays: base0 */
        if (type == TYPE1 && !pk_zero(row, base + PK_T1_RSVD_OFF, 1)) return FAILAT();
        if (type == TYPE2 && !pk_zero(row, base + PK_T2_RSVD_OFF, 1)) return FAILAT();
        if (type == TYPE3 && !pk_zero(row, base + PK_T3_RSVD_OFF, PK_T3_RSVD_BITS)) return FAILAT();
    }

    /* ---- explicit / direct children ---- */
    int nslots = (type == TYPE1) ? 2 : (type == TYPE2 ? 6 : (type == TYPE3 ? 3 : 0));
    int cbase = (type == TYPE3) ? PK_T3_DIRECT : (type == TYPE1 ? PK_T1_CHILD : PK_T2_CHILD);
    uint64_t direct_keys = 0;
    bool seen_absent = false;
    int last_key = -1;
    uint32_t nchild = 0;
    n.ch_start = static_cast<uint32_t>(children.size());
    for (int i = 0; i < nslots; ++i) {
        uint32_t v = static_cast<uint32_t>(pk_read(row, base + cbase + 32 * i, 32));
        int key = static_cast<int>(v & 0x3Fu);
        int cst = static_cast<int>((v >> 6) & 0xFu);
        uint32_t ccell = v >> 10;
        if (cst == SCAMP_ABSENT_STAGE) {
            if (v != SCAMP_CHILD_ABSENT) return FAILAT();       /* only absent encoding */
            seen_absent = true;
            continue;
        }
        if (cst > SCAMP_STAGE_MAX) return FAILAT();             /* present stages 0..10 */
        if (seen_absent) return FAILAT();                       /* present first */
        if (key <= last_key) return FAILAT();                   /* sorted, distinct */
        last_key = key;
        if (cst >= s) return FAILAT();                          /* strictly lower stage */
        if (w.depth + 6 > max) return FAILAT();                 /* child past owner max */
        direct_keys |= (1ULL << key);
        ChildRef cr;
        cr.key = static_cast<uint8_t>(key);
        cr.stage = cst;
        cr.cell = ccell;
        cr.node = -1;
        int32_t ref = static_cast<int32_t>(children.size());
        children.push_back(cr);
        ++n.ch_count;
        ++nchild;
        Work cw;
        cw.stage = cst;
        cw.cell = ccell;
        cw.bulk = false;
        cw.origin = w.origin;
        cw.depth = w.depth + 6;
        cw.region = w.region | (static_cast<u128_t>(key) << (128 - (w.depth + 6)));
        cw.parent = idx;
        cw.ref = ref;
        q.push_back(cw);
    }

    /* ---- bulk children ---- */
    if (type == TYPE3) {
        uint64_t bm = pk_read(row, base + PK_BULK_BM_OFF, PK_BULK_BM_BITS);
        uint32_t bbase = static_cast<uint32_t>(pk_read(row, base + PK_BULK_BASE_OFF, PK_BULK_BASE_BITS));
        int bstg = static_cast<int>(pk_read(row, base + PK_BULK_STG_OFF, PK_BULK_STG_BITS));
        if (bstg > SCAMP_STAGE_MAX) return FAILAT();
        if (bstg >= s) return FAILAT();
        if (bbase & 1u) return FAILAT();                        /* bulk_base even */
        uint32_t bc = scamp_popcount64(bm);
        if (bc < 4) return FAILAT();                            /* at least four bulk */
        if (static_cast<uint64_t>(bbase) + 2ull * bc > d->cells[bstg]) return FAILAT();
        if (w.depth + 6 > max) return FAILAT();
        if (bm & direct_keys) return FAILAT();                  /* disjoint keys */
        uint32_t i = 0;
        for (int k = 0; k < 64; ++k) {
            if (!((bm >> k) & 1ULL)) continue;
            ChildRef cr;
            cr.key = static_cast<uint8_t>(k);
            cr.stage = bstg;
            cr.cell = bbase + 2 * i;
            cr.node = -1;
            int32_t ref = static_cast<int32_t>(children.size());
            children.push_back(cr);
            ++n.ch_count;
            ++nchild;
            Work cw;
            cw.stage = bstg;
            cw.cell = cr.cell;
            cw.bulk = true;
            cw.origin = w.origin;
            cw.depth = w.depth + 6;
            cw.region = w.region | (static_cast<u128_t>(k) << (128 - (w.depth + 6)));
            cw.parent = idx;
            cw.ref = ref;
            q.push_back(cw);
            ++i;
        }
    }

    if (type == TYPE2 && (nchild < 3 || nchild > 6)) return FAILAT();
    if (type == TYPE3 && (nchild < 7 || nchild > 64)) return FAILAT();

    /* ---- owned prefixes ---- */
    if (type == TYPE4 || type == TYPE5) {
        int ninl = (type == TYPE4) ? 1 : 2;
        if (type == TYPE4 && !pk_zero(row, base + PK_T4_RSVD_OFF, PK_T4_RSVD_BITS)) return FAILAT();
        if (type == TYPE5 && !pk_zero(row, base + PK_T5_RSVD_OFF, PK_T5_RSVD_BITS)) return FAILAT();
        n.ninl = static_cast<uint8_t>(ninl);
        for (int i = 0; i < ninl; ++i) {
            int pos = base + (i == 0 ? PK_INL0_OFF : PK_INL1_OFF);
            uint64_t frag = pk_read(row, pos, PK_INL_FRAG_BITS);
            uint32_t len8 = static_cast<uint32_t>(pk_read(row, pos + PK_INL_FRAG_BITS, PK_INL_LEN_BITS));
            uint32_t hop = static_cast<uint32_t>(
                pk_read(row, pos + PK_INL_FRAG_BITS + PK_INL_LEN_BITS, PK_INL_HOP_BITS));
            if (hop > SCAMP_HOP_MAX) return FAILAT();
            uint64_t hi = 0, lo = 0;
            int L = 0;
            if (w.origin == 0) {
                if (len8 > 16) return FAILAT();
                hi = frag;
                L = static_cast<int>(len8);
            } else if (w.origin == 16) {
                if (len8 < 1 || len8 > 48) return FAILAT();
                uint64_t key16 = scamp_bits(w.region, 0, 16);
                hi = (key16 << 48) | (frag >> 16);
                L = 16 + static_cast<int>(len8);
            } else {
                if (len8 < 1 || len8 > 64) return FAILAT();
                hi = scamp_hi(w.region);
                lo = frag;
                L = 64 + static_cast<int>(len8);
            }
            ScampPrefix p;
            p.addr = scamp_make128(hi, lo);
            p.len = static_cast<uint8_t>(L);
            p.hop = hop;
            if (scamp_mask(p.addr, L) != p.addr) return FAILAT();           /* host bits clear */
            if (L < w.depth) return FAILAT();                               /* reaches the node */
            if (L > max) return FAILAT();
            if (scamp_mask(p.addr, w.depth) != w.region) return FAILAT();   /* inside region */
            n.inl[i] = p;
            fib.push_back(p);
            if (fib.size() > SCAMP_PREFIX_LIMIT) return FAILAT();
        }
    } else {
        int minL = (w.origin == 0) ? 0 : (w.origin == 16 ? 17 : 65);
        uint32_t off = 0;
        for (int p = 1; p < 64; ++p) {
            if (!((n.pattern >> p) & 1ULL)) continue;
            int l = 31 - __builtin_clz(static_cast<unsigned>(p));
            uint32_t v = static_cast<uint32_t>(p - (1 << l));
            int L = w.depth + l;
            if (L > max || L < minL) return FAILAT();
            u128_t addr = w.region;
            if (l > 0) addr |= (static_cast<u128_t>(v) << (128 - L));
            uint32_t hop = d->nexthops[n.ni_base + off];
            ++off;
            if (hop > SCAMP_HOP_MAX) return FAILAT();
            ScampPrefix sp;
            sp.addr = addr;
            sp.len = static_cast<uint8_t>(L);
            sp.hop = hop;
            fib.push_back(sp);
            if (fib.size() > SCAMP_PREFIX_LIMIT) return FAILAT();
        }
    }
    return true;
}

bool Validator::finish() {
    /* charged slots cover [0,cells) densely; no unused nonempty data */
    for (int s = 0; s < RAM_NUM; ++s) {
        for (uint32_t c = 0; c < d->cells[s]; ++c)
            if (cover[s][c] < 0) return FAILAT();
        if (d->cells[s] & 1u) {
            const Row256& row = d->banks[s][d->cells[s] / 2];
            if (!pk_zero(row, 128, 128)) return FAILAT();      /* final upper half zero */
        }
    }
    for (size_t i = 0; i < children.size(); ++i) {
        const ChildRef& cr = children[i];
        if (cr.stage < 0 || cr.stage >= RAM_NUM) return FAILAT();
        if (cr.cell >= d->cells[cr.stage]) return FAILAT();
        int32_t id = cover[cr.stage][cr.cell];
        if (id < 0) return FAILAT();
        if (nodes[id].cell != cr.cell) return FAILAT();         /* exact slot start */
        if (id != cr.node) return FAILAT();
    }

    /* owned prefixes, bottom-up (child stages are strictly lower) */
    std::vector<int32_t> by_stage[RAM_NUM];
    for (size_t i = 0; i < nodes.size(); ++i)
        by_stage[nodes[i].stage].push_back(static_cast<int32_t>(i));
    for (int s = 0; s < RAM_NUM; ++s) {
        for (size_t j = 0; j < by_stage[s].size(); ++j) {
            int32_t idx = by_stage[s][j];
            ValNode& n = nodes[idx];
            uint32_t owned;
            if (n.type == TYPE4) owned = 1;
            else if (n.type == TYPE5) owned = 2;
            else owned = scamp_popcount64(n.pattern);
            for (uint8_t k = 0; k < n.ch_count; ++k) {
                const ChildRef& cr = children[n.ch_start + k];
                if (cr.node < 0) return FAILAT();
                const ValNode& ch = nodes[cr.node];
                if (ch.parent != idx) return FAILAT();          /* exactly one parent */
                owned += ch.owned;
                if (owned > SCAMP_PREFIX_LIMIT) return FAILAT();
            }
            n.owned = owned;
            if (n.type <= TYPE3 && owned < 3) return FAILAT();  /* larger subtrees only */
            if (n.type == TYPE4 && owned != 1) return FAILAT();
            if (n.type == TYPE5 && owned != 2) return FAILAT();
        }
    }

    /* complete FIB: distinct and bounded */
    std::sort(fib.begin(), fib.end(), [](const ScampPrefix& a, const ScampPrefix& b) {
        if (a.addr != b.addr) return a.addr < b.addr;
        return a.len < b.len;
    });
    for (size_t i = 1; i < fib.size(); ++i)
        if (fib[i].addr == fib[i - 1].addr && fib[i].len == fib[i - 1].len) return FAILAT();
    if (fib.size() > SCAMP_PREFIX_LIMIT) return FAILAT();

    /* global BMP fallbacks */
    {
        LiveFib lf;
        for (size_t i = 0; i < fib.size(); ++i) lf.put(fib[i].addr, fib[i].len, fib[i].hop);
        for (size_t i = 0; i < nodes.size(); ++i) {
            const ValNode& n = nodes[i];
            nexthop_t v = lf.lookup_bounded(n.region, n.depth);
            uint32_t want = (v == LPM_INVALID_NH) ? SCAMP_BMP_NULL : static_cast<uint32_t>(v);
            if (n.bmp != want) return FAILAT();
        }
    }

    /* NI dictionary: distinct used patterns, increasing order */
    {
        std::vector<uint64_t> used;
        for (size_t i = 0; i < nodes.size(); ++i)
            if (nodes[i].type <= TYPE3) used.push_back(nodes[i].pattern);
        std::sort(used.begin(), used.end());
        used.erase(std::unique(used.begin(), used.end()), used.end());
        if (used.size() != d->bitmaps.size()) return FAILAT();
        for (size_t i = 0; i < used.size(); ++i) if (used[i] != d->bitmaps[i]) return FAILAT();
    }
    /* NI arrays: disjoint, no holes, complete coverage */
    {
        std::vector<unsigned char> mark(d->nexthops.size(), 0);
        for (size_t i = 0; i < nodes.size(); ++i) {
            const ValNode& n = nodes[i];
            if (n.type > TYPE3) continue;
            uint32_t pc = scamp_popcount64(n.pattern);
            if (pc == 0) {
                if (n.ni_base != 0) return FAILAT();
                continue;
            }
            if (static_cast<uint64_t>(n.ni_base) + pc > mark.size()) return FAILAT();
            for (uint32_t k = 0; k < pc; ++k) {
                if (mark[n.ni_base + k]) return FAILAT();
                mark[n.ni_base + k] = 1;
            }
        }
        for (size_t i = 0; i < mark.size(); ++i) if (!mark[i]) return FAILAT();
    }

    /* fronts complete and tagged; root present exactly for the depth-0 group */
    {
        bool has0 = false;
        std::vector<uint64_t> k16, k64;
        for (size_t i = 0; i < fib.size(); ++i) {
            const ScampPrefix& p = fib[i];
            if (p.len <= 16) has0 = true;
            else if (p.len <= 64) k16.push_back(static_cast<uint64_t>(p.addr >> 112));
            else k64.push_back(scamp_hi(p.addr));
        }
        std::sort(k16.begin(), k16.end());
        k16.erase(std::unique(k16.begin(), k16.end()), k16.end());
        std::sort(k64.begin(), k64.end());
        k64.erase(std::unique(k64.begin(), k64.end()), k64.end());
        if (has0 != (d->root.stage >= 0)) return FAILAT();
        if (d->front16.size() != k16.size()) return FAILAT();
        if (d->front64.size() != k64.size()) return FAILAT();
        for (size_t i = 0; i < k16.size(); ++i) if (d->front16[i].key != k16[i]) return FAILAT();
        for (size_t i = 0; i < k64.size(); ++i) if (d->front64[i].key != k64[i]) return FAILAT();
    }

    /* parsed lookup graph */
    out->clear();
    out->nodes.resize(nodes.size());
    for (size_t i = 0; i < nodes.size(); ++i) {
        const ValNode& n = nodes[i];
        ImageQueryNode& qn = out->nodes[i];
        qn.type = n.type;
        qn.depth = n.depth;
        qn.origin = n.origin;
        qn.bmp = n.bmp;
        qn.pattern = n.pattern;
        qn.ni_base = n.ni_base;
        qn.ninl = (n.type >= TYPE4) ? n.ninl : 0;
        for (int k = 0; k < qn.ninl; ++k) {
            qn.inl_addr[k] = n.inl[k].addr;
            qn.inl_len[k] = n.inl[k].len;
            qn.inl_hop[k] = n.inl[k].hop;
        }
        std::vector<ChildRef> refs;
        for (uint8_t k = 0; k < n.ch_count; ++k) refs.push_back(children[n.ch_start + k]);
        std::sort(refs.begin(), refs.end(),
                  [](const ChildRef& a, const ChildRef& b) { return a.key < b.key; });
        qn.child_start = static_cast<uint32_t>(out->child_key.size());
        qn.nchild = static_cast<uint8_t>(refs.size());
        for (size_t k = 0; k < refs.size(); ++k) {
            out->child_key.push_back(refs[k].key);
            out->child_node.push_back(refs[k].node);
        }
    }
    out->root = (d->root.stage >= 0) ? resolve(d->root) : -1;
    if (d->root.stage >= 0 && out->root < 0) return FAILAT();
    for (size_t i = 0; i < d->front16.size(); ++i) {
        int32_t id = resolve(d->front16[i].loc);
        if (id < 0) return FAILAT();
        out->front16.push_back(std::make_pair(d->front16[i].key, id));
    }
    for (size_t i = 0; i < d->front64.size(); ++i) {
        int32_t id = resolve(d->front64[i].loc);
        if (id < 0) return FAILAT();
        out->front64.push_back(std::make_pair(d->front64[i].key, id));
    }
    return true;
}

bool Validator::run() {
    if (!shape()) return FAILAT();
    for (int s = 0; s < RAM_NUM; ++s) cover[s].assign(d->cells[s], -1);
    if (d->root.stage >= 0) {
        Work w;
        w.stage = d->root.stage;
        w.cell = d->root.cell;
        w.origin = 0;
        w.depth = 0;
        w.region = 0;
        q.push_back(w);
    }
    for (size_t i = 0; i < d->front16.size(); ++i) {
        Work w;
        w.stage = d->front16[i].loc.stage;
        w.cell = d->front16[i].loc.cell;
        w.origin = 16;
        w.depth = 16;
        w.region = static_cast<u128_t>(d->front16[i].key) << 112;
        q.push_back(w);
    }
    for (size_t i = 0; i < d->front64.size(); ++i) {
        Work w;
        w.stage = d->front64[i].loc.stage;
        w.cell = d->front64[i].loc.cell;
        w.origin = 64;
        w.depth = 64;
        w.region = static_cast<u128_t>(d->front64[i].key) << 64;
        q.push_back(w);
    }
    for (size_t i = 0; i < q.size(); ++i)
        if (!visit(q[i])) return FAILAT();
    return finish();
}

} /* namespace */

bool validate_image(const ImageData& d, ParsedImage& out) {
    scamp_validate_error.clear();
    Validator v;
    v.d = &d;
    ParsedImage tmp;
    v.out = &tmp;
    if (!v.run()) {
        if (scamp_validate_error.empty()) scamp_validate_error = "unknown";
        return false;
    }
    out = std::move(tmp);
    return true;
}
